// A stand-in analytics service. In a real app this would POST to an
// external provider (Segment, PostHog, a data warehouse, etc.).
export async function logPageView(event: {
  page: string
  timestamp: number
}): Promise<void> {
  // Simulate network latency to the analytics provider so it's clear why
  // this should not block the response.
  await new Promise((resolve) => setTimeout(resolve, 500))
  console.log('[analytics] page view logged:', event)
}

