import { after } from 'next/server'
import { logPageView } from './analytics'

export default function Home() {
  // Schedule analytics logging to run *after* the response has finished
  // streaming to the client. This keeps the request off the critical path,
  // so a slow analytics call never delays what the user sees.
  after(async () => {
    await logPageView({ page: '/', timestamp: Date.now() })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting — your page view is being recorded in the background.</p>
    </main>
  )
}

